INSERT INTO ppr_product_spec (`id`, `code`, `name`, `category_id`, `outer_diameter_mm`, `wall_thickness_mm`, `outer_lower_mm`, `outer_upper_mm`, `wall_lower_mm`, `wall_upper_mm`, `ovality_upper_mm`, `status`, `created_at`, `updated_at`) VALUES (2, 'SPEC-20X3.4', 'PPR S2.5 20×3.4 管', 1, '20.000', '3.400', '20.000', '20.400', '3.400', '4.000', '0.300', 'enabled', '2026-10-13 01:36:53', '2026-10-13 01:36:53');
INSERT INTO ppr_batch (`id`, `batch_no`, `spec_id`, `extruder_id`, `haul_off_id`, `production_group`, `start_time`, `end_time`, `status`, `data_source`, `created_at`, `updated_at`) VALUES (4, '12121D0035', 2, 1, 2, '乙班', '2026-10-12 18:00:00', '2026-10-13 02:00:00', 'completed', 'MES', '2026-10-13 01:36:53', '2026-10-13 01:36:53');
INSERT INTO ppr_product_measurement (`id`, `record_no`, `sample_no`, `batch_id`, `inspect_time`, `outer_diameter_mm`, `min_wall_thickness_mm`, `max_wall_thickness_mm`, `max_outer_diameter_mm`, `min_outer_diameter_mm`, `ovality_mm`, `data_source`, `quality_flag`, `remark`, `created_at`, `updated_at`) VALUES (16, 'IR-20261012-009', 'S-209', 4, '2026-10-12 20:00:00', '25.180', '4.310', '4.420', '25.280', '25.090', '0.190', 'MES_IMPORT', 'error', '记录值疑似跨规格录入', '2026-10-13 01:36:53', '2026-10-13 01:36:53');
INSERT INTO ppr_alert_event (`id`, `event_no`, `measurement_id`, `metric_code`, `risk_level`, `rule_code`, `rule_name`, `observed_value`, `threshold_text`, `status`, `source`, `notified_level`, `notified_at`, `detected_at`, `created_at`, `updated_at`) VALUES (51, 'QE-20261012-016WT', 16, 'min_wall_thickness', 'high', 'R3', '超出标准区间', '4.3100', '3.400 mm–4.000 mm，实测 4.310 mm，高于上限 0.310 mm', 'analyzing', 'engine', 'high', '2026-10-14 01:35:32', '2026-10-12 20:00:00', '2026-10-13 07:26:22', '2026-10-13 07:26:22');
INSERT INTO ppr_alert_event (`id`, `event_no`, `measurement_id`, `metric_code`, `risk_level`, `rule_code`, `rule_name`, `observed_value`, `threshold_text`, `status`, `source`, `notified_level`, `notified_at`, `detected_at`, `created_at`, `updated_at`) VALUES (50, 'QE-20261012-016OD', 16, 'outer_diameter', 'high', 'R3', '超出标准区间', '25.1800', '20.000 mm–20.400 mm，实测 25.180 mm，高于上限 4.780 mm', 'open', 'engine', 'high', '2026-10-14 01:35:32', '2026-10-12 20:00:00', '2026-10-13 07:26:22', '2026-10-13 07:26:22');
INSERT INTO ppr_alert_event (`id`, `event_no`, `measurement_id`, `metric_code`, `risk_level`, `rule_code`, `rule_name`, `observed_value`, `threshold_text`, `status`, `source`, `notified_level`, `notified_at`, `detected_at`, `created_at`, `updated_at`) VALUES (52, 'QE-20261012-016OV', 16, 'ovality', 'normal', 'R0', '在标准区间内', '0.1900', '0.000 mm–0.300 mm，实测 0.190 mm，未进入接近带', 'closed', 'engine', NULL, NULL, '2026-10-12 20:00:00', '2026-10-13 07:26:22', '2026-10-13 07:26:22');
INSERT INTO ppr_analysis_run (`id`, `run_no`, `alert_id`, `status`, `summary`, `evidence_snapshot`, `engine_type`, `model_name`, `prompt_version`, `agent_version`, `tool_trace_json`, `token_usage_json`, `raw_response_json`, `latency_ms`, `fallback_reason`, `generated_by`, `generated_at`, `updated_at`) VALUES (10, 'AN-20261013084753-SEV9', 51, 'generated', '事件 QE-20261012-016WT（触发规则 R3 超出标准区间）：2026-10-12 20:00 检验记录 IR-20261012-009（样品 S-209，批次 12121D0035，乙班，规格 PPR S2.5 20×3.4）实测 min_wall_thickness=4.310 mm，高于产品规格上限 4.000 mm 达 0.310 mm，系统标记风险等级 high，状态 open。同期 SCADA 仅有 1 条设备记录（EQ-EX-01，采集时间同为 20:00，备注“换规格后首件”），缺前后对比窗口。本批测量序列仅返回该 1 条记录且其 quality_flag=error、备注“记录值疑似跨规格录入”，同时外径实测 25.18 mm 明显偏离规格外径范围 20.000–20.400 mm，故当前数据存在录入口径错误的重大可能。分析边界：仅基于工具返回数据，未获取参考批次数值、设备前后窗口与原始检验凭证，不得据此判定最终根因。', '[object Object]', 'agent', 'deepseek-v4-flash', 'quality-agent-v1.0', 'langchain-create-agent-v1', '[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object]', '[object Object]', '[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object]', 14434, NULL, '流式过程验证', '2026-10-13 08:47:53', '2026-10-13 08:47:53');
INSERT INTO ppr_analysis_run (`id`, `run_no`, `alert_id`, `status`, `summary`, `evidence_snapshot`, `engine_type`, `model_name`, `prompt_version`, `agent_version`, `tool_trace_json`, `token_usage_json`, `raw_response_json`, `latency_ms`, `fallback_reason`, `generated_by`, `generated_at`, `updated_at`) VALUES (11, 'AN-20261013085302-QT7W', 51, 'generated', '事件 QE-20261012-016WT（批次 12121D0035，乙班，牌号/规格：PPR S2.5 20×3.4 管，spec_id=2），触发规则 R3「超出标准区间」，异常指标 min_wall_thickness 实测 4.310 mm，超出规格上限 4.000 mm 达 0.310 mm（下限 3.400 mm）。取证范围：预警上下文、同批次检验序列、异常时刻±1440 min 设备采集窗口、同规格参考批次记录、指标定义。关键发现：①该批次仅返回一条检验记录（S-209），quality_flag=error，备注「记录值疑似跨规格录入」；②该记录外径读数 25.18/25.09–25.28 mm，明显偏离规格外径区间 20.000–20.400 mm；③该条为「换规格后首件」，设备窗口仅有 1 条 SCADA 记录（203 ℃、11.8 MPa、牵引 7.9 m/min），无前后对比数据；④参考批次查询未返回任何数据。基于以上，本次「壁厚超上限」更可能源自测量/记录口径问题而非制程壁厚实际偏移，但需工程师验证后方可定论，本报告不作最终根因判定。', '[object Object]', 'agent', 'deepseek-v4-flash', 'quality-agent-v1.0', 'langchain-create-agent-v1', '[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object]', '[object Object]', '[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object]', 15092, NULL, '质量工程师', '2026-10-13 08:53:02', '2026-10-13 08:53:02');
INSERT INTO ppr_analysis_run (`id`, `run_no`, `alert_id`, `status`, `summary`, `evidence_snapshot`, `engine_type`, `model_name`, `prompt_version`, `agent_version`, `tool_trace_json`, `token_usage_json`, `raw_response_json`, `latency_ms`, `fallback_reason`, `generated_by`, `generated_at`, `updated_at`) VALUES (15, 'AN-20261013090419-4J62', 51, 'generated', '预警事件 QE-20261012-016WT（规则R3“超出标准区间”，指标 min_wall_thickness）于2026-10-12T20:00 触发，实测 4.310 mm，高于规格上限 4.000 mm 达 0.310 mm，风险等级 high。关联批次 12121D0035（PPR S2.5 20×3.4 管，规格ID 2，乙班），记录 IR-20261012-009 / 样品 S-209。关键异常：该记录外径实测 25.090–25.280 mm，明显超出该规格外径限值 20.000–20.400 mm（超出约 4.7 mm），且记录质量标志为 error、备注“记录值疑似跨规格录入”。本批次产品检验序列仅返回该单条记录，参考批次对照数据为空，设备数据仅返回异常时刻单点。因此本次分析以“数据口径异常优先”为边界，不认定工艺根因为最终结论。', '[object Object]', 'agent', 'deepseek-v4-flash', 'quality-agent-v1.0', 'langchain-create-agent-v1', '[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object]', '[object Object]', '[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object],[object Object]', 11524, NULL, '质量工程师', '2026-10-13 09:04:19', '2026-10-13 09:04:19');
INSERT INTO ppr_analysis_conclusion (`id`, `analysis_id`, `sort_no`, `category`, `hypothesis`, `evidence`, `missing_evidence`, `validation_action`, `confidence`, `evidence_source_ids`, `generated_by_model`, `engineer_modified`, `engineer_decision`, `engineer_comment`, `actual_finding`, `updated_by`, `created_at`, `updated_at`) VALUES (30, 10, 1, '数据有效性（首要）', '该条超限记录可能为跨规格录入错误：所录壁厚与外径均对应其他规格产品，而非 PPR S2.5 20×3.4 的实际壁厚超上限。', '记录 IR-20261012-009 自身 quality_flag=error、remark「记录值疑似跨规格录入」；实测 outer_diameter=25.180 mm（范围 25.090–25.280 mm）落在规格外径 20.000–20.400 mm 之外；min_wall_thickness=4.310、max_wall_thickness=4.420 同步偏高。', '该样品检样的原始检验单/量具记录、测量时所用产品规格设定、MES 导入日志与人工复核结论；换规格切换时点的规格确认记录。', '由质量工程师调取 IR-20261012-009 原始检验凭证与 MES 导入日志，核对样品 S-209 的实际规格标识；若确认跨规格录入，按数据修正流程更正记录并重新判定该预警有效性，再决定是否关闭事件。', '0.6800', 'E1,E2,E4', 'deepseek-v4-flash', 0, 'pending', NULL, NULL, NULL, '2026-10-13 08:47:53', '2026-10-13 08:47:53');
INSERT INTO ppr_analysis_conclusion (`id`, `analysis_id`, `sort_no`, `category`, `hypothesis`, `evidence`, `missing_evidence`, `validation_action`, `confidence`, `evidence_source_ids`, `generated_by_model`, `engineer_modified`, `engineer_decision`, `engineer_comment`, `actual_finding`, `updated_by`, `created_at`, `updated_at`) VALUES (31, 10, 2, '设备/工艺（换规格首件）', '若数据有效，本次壁厚偏高可能与“换规格后首件”阶段挤出量、牵引速度尚未稳定有关（挤出量↑或牵引速度↓会使壁厚增大）。', '同期设备记录 ER-20261012-2000（EQ-EX-01 1号挤出机，20:00）备注「换规格后首件」，参数 temperature=203.00 ℃、pressure=11.800 MPa、haul_off_speed=7.900 m/min；与预警记录同一时间点。', '异常前后完整设备窗口数据（工具仅返回 20:00 单条）、该规格首件应执行的工艺参数设定值与换规格首件放行要求、后续首件复检结果。', '调取 EQ-EX-01 在 20:00 前后各 2 小时以上的连续采集数据，与上一规格稳定生产时段参数对比，确认温度/压力/牵引速度是否存在切换期偏差，并按首件检验要求追加取样复测。', '0.3500', 'E2,E3', 'deepseek-v4-flash', 0, 'pending', NULL, NULL, NULL, '2026-10-13 08:47:53', '2026-10-13 08:47:53');
INSERT INTO ppr_analysis_conclusion (`id`, `analysis_id`, `sort_no`, `category`, `hypothesis`, `evidence`, `missing_evidence`, `validation_action`, `confidence`, `evidence_source_ids`, `generated_by_model`, `engineer_modified`, `engineer_decision`, `engineer_comment`, `actual_finding`, `updated_by`, `created_at`, `updated_at`) VALUES (32, 10, 3, '趋势与分布（最薄点代表性）', '本批缺乏可用的历史测量序列，无法判断壁厚是持续偏高还是单点跳变，也无法评估壁厚均匀性（偏心）状况。', 'get_batch_measurements 仅返回 1 条记录（id=16，即预警记录本身），无异常时刻之前的检验序列；max_wall_thickness=4.420 与 min_wall_thickness=4.310 的差值为 0.110 mm 仅来自同一记录。', '本批异常前 10 个以上检验点数据、同批多点壁厚分布与偏心测量数据。', '向 MES/检验班组补齐批次 12121D0035 在 2026-10-12 20:00 前后的完整检验序列及同一样品多点壁厚数据，重建趋势后再判断是否构成系统性偏移。', '0.7500', 'E1,E2', 'deepseek-v4-flash', 0, 'pending', NULL, NULL, NULL, '2026-10-13 08:47:53', '2026-10-13 08:47:53');
INSERT INTO ppr_analysis_conclusion (`id`, `analysis_id`, `sort_no`, `category`, `hypothesis`, `evidence`, `missing_evidence`, `validation_action`, `confidence`, `evidence_source_ids`, `generated_by_model`, `engineer_modified`, `engineer_decision`, `engineer_comment`, `actual_finding`, `updated_by`, `created_at`, `updated_at`) VALUES (33, 10, 4, '对照基准（跨批次）', '缺少同规格其他正常批次的壁厚实测数据，无法判断 4.310 mm 在本规格历史分布中是否确属离群。', 'get_reference_measurements 两次调用均返回空结果，无相同规格（PPR S2.5 20×3.4，spec_id=2）的其他批次测量记录可供对照。', '同规格正常批次壁厚实测样本、产品规格限值以外的内控警戒线与过程能力数据。', '补充查询同规格正常批次的 min_wall_thickness 实测分布（建议 ≥20 条），形成参考基线后评估本次偏离程度；注意跨批次差异不等同正式控制限。', '0.8000', 'E5', 'deepseek-v4-flash', 0, 'pending', NULL, NULL, NULL, '2026-10-13 08:47:53', '2026-10-13 08:47:53');
INSERT INTO ppr_analysis_conclusion (`id`, `analysis_id`, `sort_no`, `category`, `hypothesis`, `evidence`, `missing_evidence`, `validation_action`, `confidence`, `evidence_source_ids`, `generated_by_model`, `engineer_modified`, `engineer_decision`, `engineer_comment`, `actual_finding`, `updated_by`, `created_at`, `updated_at`) VALUES (34, 10, 5, '判定口径', '预警判定依据为产品规格限值（3.400–4.000 mm），本次触发为超上限；但口径上最薄点不能代表整体壁厚分布，单点超上限是否等同整批不合格需进一步确认。', 'metric_code=min_wall_thickness 单位 mm，产品规格限值来源为 ppr_product_spec（lower=3.400，upper=4.000）；指标说明明确「仅最薄点不能代表整体壁厚分布」。', '该规格对壁厚超上限的处置规程（复检/降级/放行条件）、同一样品多点壁厚与偏心测量数据。', '由质量工程师依据规格与检验规程确认超上限记录的处置路径，并对留样执行多点壁厚复测后判定该批次壁厚符合性。', '0.5500', 'E1,E6', 'deepseek-v4-flash', 0, 'pending', NULL, NULL, NULL, '2026-10-13 08:47:53', '2026-10-13 08:47:53');
INSERT INTO ppr_analysis_conclusion (`id`, `analysis_id`, `sort_no`, `category`, `hypothesis`, `evidence`, `missing_evidence`, `validation_action`, `confidence`, `evidence_source_ids`, `generated_by_model`, `engineer_modified`, `engineer_decision`, `engineer_comment`, `actual_finding`, `updated_by`, `created_at`, `updated_at`) VALUES (35, 11, 1, '数据可信性/记录口径', '本次 min_wall_thickness=4.310 mm 的超限可能源于跨规格录入或样本/规格错配，而非该规格真实壁厚超上限。', '预警记录 quality_flag=error、remark「记录值疑似跨规格录入」（来源 E1）；同批次唯一检验记录外径 25.180 mm、外径范围 25.090–25.280 mm（来源 E2），而产品规格外径限值为 20.000–20.400 mm（来源 E1）；壁厚上限 4.000 mm（来源 E3）。', '原始检验单/测量原始数据、样本 S-209 的实际规格标识、跨规格录入的更正记录或复核结论。', '调取 IR-20261012-009 原始记录与 MES 导入日志，核对样本 S-209 对应规格与外径/壁厚实测的原始录入值，确认是否为跨规格数据挂错批次；如确认错录，按数据更正流程处理并重跑判定。', '0.6200', 'E1,E2,E3', 'deepseek-v4-flash', 0, 'pending', NULL, NULL, NULL, '2026-10-13 08:53:02', '2026-10-13 08:53:02');
INSERT INTO ppr_analysis_conclusion (`id`, `analysis_id`, `sort_no`, `category`, `hypothesis`, `evidence`, `missing_evidence`, `validation_action`, `confidence`, `evidence_source_ids`, `generated_by_model`, `engineer_modified`, `engineer_decision`, `engineer_comment`, `actual_finding`, `updated_by`, `created_at`, `updated_at`) VALUES (36, 11, 2, '测量代表性', '单点最薄壁厚不足代表整体壁厚分布与偏心状况，当前判定可能被单点读数放大。', '指标定义说明「仅最薄点不能代表整体壁厚分布」，影响因素含挤出量、牵引速度、模具偏心、原料波动（来源 E3）；本批次仅返回 1 条检验记录（来源 E2）。', '同一样本/同批次的多点壁厚、圆周壁厚分布、偏心度数据以及后续样本检验序列。', '对该批次补测多点壁厚与圆周分布，并提取异常时刻前后的连续检验序列，判断是单点异常还是批次性偏移。', '0.4500', 'E2,E3', 'deepseek-v4-flash', 0, 'pending', NULL, NULL, NULL, '2026-10-13 08:53:02', '2026-10-13 08:53:02');
INSERT INTO ppr_analysis_conclusion (`id`, `analysis_id`, `sort_no`, `category`, `hypothesis`, `evidence`, `missing_evidence`, `validation_action`, `confidence`, `evidence_source_ids`, `generated_by_model`, `engineer_modified`, `engineer_decision`, `engineer_comment`, `actual_finding`, `updated_by`, `created_at`, `updated_at`) VALUES (37, 11, 3, '制程稳定性/换规格首件', '该记录为「换规格后首件」，换规格初期工艺尚未稳定可能导致壁厚偏大，需验证是否与规格切换相关。', '设备窗口唯一记录 ER-20261012-2000 备注「换规格后首件」，采集时间与预警时刻一致（2026-10-12T20:00:00Z），温度 203.00 ℃、压力 11.800 MPa、牵引速度 7.900 m/min（来源 E4）。', '换规格前后更长时间窗口的温度/压力/牵引速度序列与历史首件对比数据；本次窗口仅 1 条记录，无法建立趋势。', '调取换规格前后各 4 小时以上 SCADA 数据，比对温度、压力、牵引速度的稳定性与设定值吻合情况，并核查历史上同规格切换首件的壁厚表现。', '0.3500', 'E4', 'deepseek-v4-flash', 0, 'pending', NULL, NULL, NULL, '2026-10-13 08:53:02', '2026-10-13 08:53:02');
INSERT INTO ppr_analysis_conclusion (`id`, `analysis_id`, `sort_no`, `category`, `hypothesis`, `evidence`, `missing_evidence`, `validation_action`, `confidence`, `evidence_source_ids`, `generated_by_model`, `engineer_modified`, `engineer_decision`, `engineer_comment`, `actual_finding`, `updated_by`, `created_at`, `updated_at`) VALUES (38, 11, 4, '对照基线缺失', '缺少同规格正常批次对照，尚无法判断 4.310 mm 是否为本规格历史常见水平。', '同规格参考批次查询未返回任何记录（来源 E5）；同批次检验序列亦仅 1 条（来源 E2）。', '同规格（spec_id=2）正常批次的壁厚分布、均值与波动范围。', '补充检索同规格历史批次检验数据，建立该规格壁厚分布基线，再评估本批次偏差量级。', '0.3000', 'E2,E5', 'deepseek-v4-flash', 0, 'pending', NULL, NULL, NULL, '2026-10-13 08:53:02', '2026-10-13 08:53:02');
INSERT INTO ppr_analysis_conclusion (`id`, `analysis_id`, `sort_no`, `category`, `hypothesis`, `evidence`, `missing_evidence`, `validation_action`, `confidence`, `evidence_source_ids`, `generated_by_model`, `engineer_modified`, `engineer_decision`, `engineer_comment`, `actual_finding`, `updated_by`, `created_at`, `updated_at`) VALUES (39, 11, 5, '设备/工艺参数相关性（仅线索）', '同期设备参数（203 ℃、11.8 MPa、7.9 m/min）可能与壁厚异常存在关联，但当前不足以证明因果。', '设备窗口在 20:00 记录温度 203.00 ℃、压力 11.800 MPa、牵引速度 7.900 m/min（来源 E4）；指标定义将挤出量、牵引速度、模具偏心列为壁厚影响因素（来源 E3）。', '这些参数的工艺设定值与允差范围、参数与壁厚的历史相关性数据、同窗口的多点采集序列。', '获取该规格工艺卡设定值与允差，核对实测参数是否在范围内，并做参数-壁厚相关性分析后再判断。', '0.2500', 'E3,E4', 'deepseek-v4-flash', 0, 'pending', NULL, NULL, NULL, '2026-10-13 08:53:02', '2026-10-13 08:53:02');
INSERT INTO ppr_analysis_conclusion (`id`, `analysis_id`, `sort_no`, `category`, `hypothesis`, `evidence`, `missing_evidence`, `validation_action`, `confidence`, `evidence_source_ids`, `generated_by_model`, `engineer_modified`, `engineer_decision`, `engineer_comment`, `actual_finding`, `updated_by`, `created_at`, `updated_at`) VALUES (57, 15, 1, '数据口径', '触发值 4.310 mm 可能属于其他规格的测量记录被错误关联到 PPR S2.5 20×3.4 规格（记录备注已提示“疑似跨规格录入”）。', '记录 IR-20261012-009 quality_flag=error、remark=“记录值疑似跨规格录入”；实测外径 25.180/25.280/25.090 mm 与规格外径限值 20.000–20.400 mm 不符（来源 S1、S2）。', '该样品对应的实际生产规格与原始测量单据；MES 导入映射与核对记录；同一样品是否存在正确规格下的重复记录。', '调取 IR-20261012-009 原始检验单与 MES 导入日志，确认样品 S-209 的实际规格与录入路径；必要时作废或重新关联该记录。', '0.7200', 'S1,S2', 'deepseek-v4-flash', 0, 'pending', NULL, NULL, NULL, '2026-10-13 09:04:19', '2026-10-13 09:04:19');
INSERT INTO ppr_analysis_conclusion (`id`, `analysis_id`, `sort_no`, `category`, `hypothesis`, `evidence`, `missing_evidence`, `validation_action`, `confidence`, `evidence_source_ids`, `generated_by_model`, `engineer_modified`, `engineer_decision`, `engineer_comment`, `actual_finding`, `updated_by`, `created_at`, `updated_at`) VALUES (58, 15, 2, '限值与判定', '若该记录归属其他规格，则不适应用本规格判定限值 3.400–4.000 mm，本次“超上限”可能为误判。', '指标定义确认 min_wall_thickness 判定限值为 3.400–4.000 mm（来源 S2）；而触发记录的外径完全偏离本规格外径限值，提示使用限值可能不匹配（来源 S1）。', '被错误关联前的目标规格限值定义；跨规格记录的正式判定流程文件。', '由质量工程师确认该记录应适用的规格限值，并在数据修正后重新跑规则 R3。', '0.6000', 'S1,S2', 'deepseek-v4-flash', 0, 'pending', NULL, NULL, NULL, '2026-10-13 09:04:19', '2026-10-13 09:04:19');
INSERT INTO ppr_analysis_conclusion (`id`, `analysis_id`, `sort_no`, `category`, `hypothesis`, `evidence`, `missing_evidence`, `validation_action`, `confidence`, `evidence_source_ids`, `generated_by_model`, `engineer_modified`, `engineer_decision`, `engineer_comment`, `actual_finding`, `updated_by`, `created_at`, `updated_at`) VALUES (59, 15, 3, '工艺关联', '设备侧“换规格后首件”状态可能是壁厚/外径尺寸偏大的相关线索（仅相关，非因果）。', '设备数据 ER-20261012-2000（EQ-EX-01 挤出机）采集时刻与预警时刻同为 2026-10-12T20:00，remark=“换规格后首件”，温度 203.00℃、压力 11.800 MPa、牵引 7.900 m/min（来源 S3）。', '换规格前后的设定值/实际值对比、该设备历史同规格正常批次的尺寸数据、换规格作业确认记录。', '核查换规格作业指导与首件确认记录，并调取换规格前后各若干小时的挤出量、牵引速度、温度曲线，做前后对比。', '0.3500', 'S3', 'deepseek-v4-flash', 0, 'pending', NULL, NULL, NULL, '2026-10-13 09:04:19', '2026-10-13 09:04:19');
INSERT INTO ppr_analysis_conclusion (`id`, `analysis_id`, `sort_no`, `category`, `hypothesis`, `evidence`, `missing_evidence`, `validation_action`, `confidence`, `evidence_source_ids`, `generated_by_model`, `engineer_modified`, `engineer_decision`, `engineer_comment`, `actual_finding`, `updated_by`, `created_at`, `updated_at`) VALUES (60, 15, 4, '趋势与波动', '该批次是否存在连续偏大趋势无法判断，因本批次仅返回单条检验记录。', 'get_batch_measurements 返回异常时刻之前的序列仅 1 条记录（IR-20261012-009），无前序样本（来源 S1）。', '同批次 12121D0035 的前序与后续检验记录（外径、壁厚、椭圆度序列）。', '从 MES 补取批次 12121D0035 全部检验记录，绘制壁厚/外径趋势与离散图后重新评估。', '0.8500', 'S1', 'deepseek-v4-flash', 0, 'pending', NULL, NULL, NULL, '2026-10-13 09:04:19', '2026-10-13 09:04:19');
INSERT INTO ppr_analysis_conclusion (`id`, `analysis_id`, `sort_no`, `category`, `hypothesis`, `evidence`, `missing_evidence`, `validation_action`, `confidence`, `evidence_source_ids`, `generated_by_model`, `engineer_modified`, `engineer_decision`, `engineer_comment`, `actual_finding`, `updated_by`, `created_at`, `updated_at`) VALUES (61, 15, 5, '对照基准', '缺少同规格正常批次对照，无法判断 4.310 mm 是否属于该规格的常见波动范围。', 'get_reference_measurements 多次调用（limit=15、30）均返回空结果（来源 S4）。', '相同规格（spec_id=2）其他正常批次的最小壁厚分布。', '扩充参考批次数据源覆盖范围；若确实无同规格历史数据，应在分析结论中标注为基准缺失而非合格。', '0.8000', 'S4', 'deepseek-v4-flash', 0, 'pending', NULL, NULL, NULL, '2026-10-13 09:04:19', '2026-10-13 09:04:19');
